const fs = require('node:fs')
const path = require('node:path')
const YAML = require('yaml')
const { isDeepStrictEqual } = require('node:util')
const { execFileSync } = require('node:child_process')
const REQUEST =
  "vars.PRIORITY_CI_ENABLED == 'true' && github.event_name == 'pull_request' && github.event.pull_request.state == 'open' && github.event.pull_request.draft == false && github.event.repository.private == false && github.event.pull_request.head.repo.full_name == github.repository && github.event.pull_request.user.type != 'Bot' && contains(github.event.pull_request.labels.*.name, 'ci:priority') && (github.event.action != 'labeled' || github.event.label.name == 'ci:priority')"
const TERMINALS = {
  'check.yml': 'check',
  'check-gitleaks.yml': 'check-gitleaks',
  'test-unit.yml': 'test-unit-status',
  'test-graphql.yml': 'test-graphql-status',
  'test-olat-api.yml': 'test-olat-api-status',
  'test-intl-production.yml': 'test-intl-production-status',
  'v3_images-stg.yml': 'build-images-status',
}
function execution(source, terminal) {
  const workflow = YAML.parse(source)
  const jobs = workflow.jobs
  delete jobs['priority-execution']
  delete jobs['priority-status']
  for (const output of [
    'admitted',
    'run_label_event',
    'run_attempt',
    'job_timeout',
    'runner_x64',
    'runner_build',
    'runner_arm',
  ]) {
    if (
      jobs['priority-route']?.outputs?.[output] !==
      '${{ steps.route.outputs.' + output + ' }}'
    )
      throw new Error(
        'canonical priority-route must map its ' + output + ' output'
      )
  }
  for (const [id, job] of Object.entries(jobs)) {
    const prefix = `!(${REQUEST}) && (`
    if (!job.if?.startsWith(prefix) || !job.if.endsWith(')'))
      throw new Error('canonical job is missing its ordinary execution gate')
    job.if = job.if.slice(prefix.length, -1)
    if (id === terminal) {
      const prefix = `\${{ (${REQUEST}) && '${terminal} (delegated)' || (`
      if (!job.name?.startsWith(prefix) || !job.name.endsWith(') }}'))
        throw new Error('canonical terminal is missing its delegated name')
      job.name = job.name.slice(prefix.length, -4)
      job.name = '${{ ' + job.name + ' }}'
    }
  }
  if (terminal === 'build-images-status') {
    const step = jobs[terminal].steps.find((step) => step.env?.PLAN_SELECTED)
    step.env.PRIORITY_JOB_NAMESPACE = 'priority-execution / '
  }
  jobs[terminal].outputs = {
    required_result: '${{ steps.priority_result.outputs.result }}',
  }
  jobs[terminal].steps.push({
    id: 'priority_result',
    if: 'always()',
    env: { TERMINAL_RESULT: '${{ job.status }}' },
    run: 'echo "result=$TERMINAL_RESULT" >> "$GITHUB_OUTPUT"',
  })
  return (
    '# Generated by .github/scripts/priority-ci-workflows.cjs; edit the canonical workflow.\n' +
    YAML.stringify(
      {
        name: workflow.name + ' priority execution',
        on: {
          workflow_call: {
            outputs: {
              required_result: {
                description: 'Actual required terminal job result',
                value: '${{ jobs.' + terminal + '.outputs.required_result }}',
              },
              run_label_event: {
                description: 'Whether label-only work was admitted',
                value: '${{ jobs.priority-route.outputs.run_label_event }}',
              },
            },
          },
        },
        ...(workflow.env ? { env: workflow.env } : {}),
        ...(workflow.permissions ? { permissions: workflow.permissions } : {}),
        jobs,
      },
      { lineWidth: 0, blockQuote: 'literal' }
    )
  )
}
function readPinnedWorkflow(root, ref, file) {
  const options = {
    cwd: root,
    encoding: 'utf8',
    env: { ...process.env, GODEBUG: 'netdns=go' },
    stdio: ['ignore', 'pipe', 'ignore'],
    timeout: 60_000,
    maxBuffer: 1024 * 1024,
  }
  try {
    try {
      execFileSync('git', ['cat-file', '-e', `${ref}^{commit}`], options)
    } catch {
      // A published executor can sit outside the current squash history.
      // Fetch its exact object without making a complete checkout shallow.
      execFileSync(
        'git',
        ['fetch', '--no-tags', '--no-write-fetch-head', 'origin', ref],
        options
      )
    }
    return execFileSync(
      'git',
      ['show', `${ref}:.github/workflows/${file}`],
      options
    )
  } catch {
    throw new Error('pinned priority workflow is unavailable: ' + file)
  }
}
function generate(root, write = false, readPinned = readPinnedWorkflow) {
  for (const [file, terminal] of Object.entries(TERMINALS)) {
    const source = fs.readFileSync(
      path.join(root, '.github/workflows', file),
      'utf8'
    )
    const target = path.join(
      root,
      '.github/workflows',
      file.replace('.yml', '-execution.yml')
    )
    const expected = execution(source, terminal)
    if (write) fs.writeFileSync(target, expected)
    else {
      const parsed = YAML.parse(expected)
      if (
        !isDeepStrictEqual(YAML.parse(fs.readFileSync(target, 'utf8')), parsed)
      )
        throw new Error('priority workflow parity is stale: ' + file)
      const uses = YAML.parse(source).jobs['priority-execution']?.uses
      const executor = file.replace('.yml', '-execution.yml')
      const prefix = `uzh-bf/klicker-uzh/.github/workflows/${executor}@`
      const ref =
        typeof uses === 'string' && uses.startsWith(prefix)
          ? uses.slice(prefix.length)
          : ''
      if (!/^[a-f0-9]{40}$/.test(ref))
        throw new Error(
          'priority workflow requires an exact executor SHA: ' + file
        )
      if (
        !isDeepStrictEqual(YAML.parse(readPinned(root, ref, executor)), parsed)
      )
        throw new Error('pinned priority workflow differs: ' + file)
    }
  }
}
if (require.main === module)
  generate(path.resolve(__dirname, '../..'), process.argv.includes('--write'))
module.exports = { REQUEST, TERMINALS, execution, generate }
